document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("noticia-form"),e=document.getElementById("lista-noticias"),t=document.getElementById("noticia-feedback");function o(){e.innerHTML="";const n=ForjaStorage.getNoticias();0!==n.length?n.reverse().forEach(n=>{e.innerHTML+=`\n\n\n<div class="vaga-admin">\n\n\n\n<h3>\n\n${n.titulo}\n\n</h3>\n\n\n\n\n<img \nsrc="${n.imagem||"assets/img/logo.png"}"\nwidth="200"\nalt="${n.titulo}"\n>\n\n\n\n\n<p>\n\n${n.conteudo}\n\n</p>\n\n\n\n<small>\n\nPublicado em:\n${n.data}\n\n</small>\n\n\n\n\n<br><br>\n\n\n\n\n<button onclick="\nexcluirNoticia(${n.id})\n">\n\nExcluir\n\n</button>\n\n\n\n</div>\n\n\n\n`}):e.innerHTML="\n\n<p>\nNenhuma notícia publicada.\n</p>\n\n"}n.addEventListener("submit",e=>{e.preventDefault();const i={titulo:document.getElementById("titulo").value,imagem:document.getElementById("imagem").value,conteudo:document.getElementById("conteudo").value};ForjaStorage.saveNoticia(i),t.textContent="Notícia publicada com sucesso!",t.style.color="green",n.reset(),o()}),window.excluirNoticia=n=>{confirm("Deseja remover esta notícia?")&&(ForjaStorage.deleteNoticia(n),o())},o()});